import numpy as np

profiles = {
150: { -100:2,-80:1,-60:12,-40:19,-20:33,0:42,20:34,40:17,60:7,80:2,100:4},
100: { -100:1,-80:1,-60:0,-40:12,-20:44,0:70,20:47,40:13,60:3,80:0,100:0},
200: { -100:3,-80:3,-60:13,-40:14,-20:22,0:25,20:20,40:19,60:7,80:2,100:1},
}

def interp(prof, x):
    xs = np.array(sorted(prof.keys()), dtype=float)
    ys = np.array([prof[k] for k in sorted(prof.keys())], dtype=float)
    if x < xs[0] or x > xs[-1]:
        return 0.0
    return float(np.interp(x, xs, ys))

def uniformity(prof, pitch, half=400, step=2):
    # sum contributions from passes at k*pitch, evaluate across one pitch period and beyond
    xs = np.arange(-half, half+1e-9, step)
    # passes that can affect |x|<half+100
    kmax = int((half+150)/pitch)+2
    film = np.zeros_like(xs)
    for k in range(-kmax, kmax+1):
        center = k*pitch
        for i,x in enumerate(xs):
            film[i] += interp(prof, x-center)
    # interior region away from edges
    mask = np.abs(xs) < (half-150)
    f = film[mask]
    return f.min(), f.max(), f.mean(), (f.max()-f.min())/f.mean()

for name, prof in profiles.items():
    print(f"\n=== standoff {name} ===")
    for pitch in [10,15,20,25,30,40,50]:
        mn,mx,mean,ripple = uniformity(prof, pitch)
        # scale so mean DFT = 100
        if mean<=0: 
            continue
        scale = 100/mean
        print(f"pitch {pitch:5.1f}  raw mean {mean:6.1f}  scaled range {mn*scale:5.1f}-{mx*scale:5.1f}  ripple {ripple*100:5.1f}%")
