def interp(prof, x):
    xs = sorted(prof.keys())
    if x < xs[0] or x > xs[-1]:
        return 0.0
    for i in range(len(xs)-1):
        if xs[i] <= x <= xs[i+1]:
            t = (x-xs[i])/(xs[i+1]-xs[i])
            return prof[xs[i]]*(1-t)+prof[xs[i+1]]*t
    return 0.0

def uniformity(prof, pitch, half=300, step=1.0):
    xs = []
    x = -half
    while x <= half:
        xs.append(x)
        x += step
    kmax = int((half+120)/pitch)+2
    film = []
    for x in xs:
        s = 0.0
        for k in range(-kmax, kmax+1):
            s += interp(prof, x - k*pitch)
        film.append(s)
    # interior
    vals = [f for x,f in zip(xs, film) if abs(x) < half-130]
    mn, mx = min(vals), max(vals)
    mean = sum(vals)/len(vals)
    return mn, mx, mean, (mx-mn)/mean if mean else 0

